import portraitUrl from '../assets/portrait-dots.png';

// One pixel per dot, generated by scripts/portrait/make_portrait.py:
// red = darkness of the area, green = how much of the cell belongs to the person (0 = no dot).
export type Grid = {
  columns: number;
  rows: number;
  tone: Float32Array;
  share: Float32Array;
  count: number;
};

let pending: Promise<Grid> | undefined;

export function loadGrid(): Promise<Grid> {
  pending ??= new Promise<Grid>((resolve, reject) => {
    const image = new Image();
    image.onload = () => {
      const canvas = document.createElement('canvas');
      canvas.width = image.naturalWidth;
      canvas.height = image.naturalHeight;
      const context = canvas.getContext('2d', { willReadFrequently: true });
      if (!context) return reject(new Error('Canvas no disponible.'));
      context.drawImage(image, 0, 0);
      const { data } = context.getImageData(0, 0, canvas.width, canvas.height);
      const size = canvas.width * canvas.height;
      const tone = new Float32Array(size);
      const share = new Float32Array(size);
      let count = 0;
      for (let i = 0; i < size; i++) {
        tone[i] = data[i * 4] / 255;
        share[i] = data[i * 4 + 1] / 255;
        if (share[i] > 0) count++;
      }
      resolve({ columns: canvas.width, rows: canvas.height, tone, share, count });
    };
    image.onerror = () => {
      pending = undefined;
      reject(new Error('No se pudo cargar el retrato.'));
    };
    image.src = portraitUrl;
  });
  return pending;
}
